insert into faculty (name_ko, name_en, title_ko, title_en, email, tel, lab_ko, lab_en, lab_url, building, room, photo_url, keywords, research_ko, bio_ko, field, is_emeritus, sort_order) values
  ('유기풍', 'Kipung Yoo', '명예교수', 'Professor Emeritus', 'kpyoo@sogang.ac.kr', null, null, null, null, null, null, 'MEDIA_BASE/faculty/0601728001508213899.jpg', null, null, '<h3>학력</h3><ul><li>University of Connecticut 공학박사(1984)</li></ul>', null, true, 6),
  ('최정우', 'Jeong-Woo Choi', '석학교수', 'Distinguished Professor', 'jwchoi@sogang.ac.kr', '02-705-8480', '나노바이오전자 소자 연구실(Nanobioelectronics Lab)', 'Nanobioelectronics Lab', 'https://nbel.sogang.ac.kr', 'F', '205', 'MEDIA_BASE/faculty/0640156001745570919.png', 'Biochemical Engineering, Nanobiotechnology, Biorobotics', '<p class="text-lg font-semibold">Biochemical Engineering, Nanobiotechnology, Biorobotics</p>', '<h3>학력</h3><ul><li>로욜라 석학교수</li></ul>', 'chair', false, 0),
  ('이성현', 'Lee, Seonghyun', '조교수', 'Assistant Professor', 'shlee@sogang.ac.kr', '02-705-8479', '미토콘드리아 생명공학 연구실', 'Mitochondrial Biotechnology Lab', 'https://mbtl.sogang.ac.kr/', 'CY', '412', 'MEDIA_BASE/faculty/0971576001788496935.jpg', 'Genome Engineering, Cell Engineering', '<p class="text-lg font-semibold">Genome Engineering · Cell Engineering</p><p>Our research lies at the interface of chemical and biomolecular engineering, genome editing, and mitochondrial biology. We view proteins, genomes, mitochondria, and cells as engineerable biological systems and apply a novel framework to control and optimize their functions.<br>At the molecular level, we engineer programmable genome-editing proteins and optimize their activity, specificity, and delivery. At the cellular level, we precisely modify mitochondrial genomes and quantitatively investigate how genetic alterations affect heteroplasmy, cellular metabolism, and disease phenotypes. These findings are further translated into genetic disease models, therapeutic genome-editing strategies, and engineered cell systems with improved functions for biomedical and industrial applications.<br>We also develop molecular detection and functional analysis technologies for disease diagnosis and the quality assessment of engineered cells. By integrating molecular design, cellular process engineering, quantitative characterization, and therapeutic validation, we aim to establish scalable bioengineering platforms for mitochondrial disorders and other human diseases.</p>', '<h3>학력</h3><ul><li>서강대학교 화학과, 이학박사 (2020)</li><li>서강대학교 화공생명공학과/바이오융합기술, 공학사/공학사 (2014)</li></ul><h3>경력</h3><ul><li>2026.09-현재: 서강대학교 화공생명공학과 부교수</li><li>2023.08-2026.08: 성균관대학교 의과대학 메타바이오헬스학과 조교수·부교수</li><li>2022.08-2023.08: 엣진(Edgene Inc.) 수석연구원(연구개발팀장)</li><li>2022.03-2022.08: 기초과학연구원 유전체교정연구단 연구위원(팀 리더)</li><li>2020.03-2022.02: 기초과학연구원 유전체교정연구단 선임연구원</li></ul><h3>주요 논문</h3><p>1. Kim S, Kim J, Cha S, et al. “In vivo mitochondrial base editing restores genotype and visual function in a mouse model of LHON.” Nature Communications. 2025;16:10923.<br>2. Kim S, Park SG, Kim J, et al. “Comprehensive phenotypic assessment of mitochondrial ND5 nonsense mutation in mice.” Experimental and Molecular Medicine. 2024;56:2395-2408.<br>3. Cho SI, Lim K, Hong S, et al. “Engineering TALE-linked deaminases to facilitate precision adenine base editing in mitochondrial DNA.” Cell. 2024;187:95-109.e26.<br>4. Lee S, Lee H, Baek G, Kim JS. “Precision mitochondrial DNA editing with high-fidelity DddA-derived base editors.” Nature Biotechnology. 2023;41:378-386.<br>5. Lee S, Lee H, Baek G, et al. “Enhanced mitochondrial DNA editing in mice using nuclear-exported TALE-linked deaminases and nucleases.” Genome Biology. 2022;23:211.<br>6. Cho SI, Lee S, Mok YG, et al. “Targeted A-to-G base editing in human mitochondrial DNA with programmable deaminases.” Cell. 2022;185:1764-1776.e12</p>', null, false, 2),
  ('임종성', null, '명예교수', 'Professor Emeritus', 'limjs@sogang.ac.kr', null, null, null, null, null, null, 'MEDIA_BASE/faculty/0087790001772614347.jpg', null, null, '<h3>학력</h3><ul><li>고려대학교 공학사(1984)</li><li>고려대학교 공학석사(1988)</li><li>고려대학교 공학박사(1993)</li></ul>', null, true, 0),
  ('박흥목', 'Hyngmok Park', '명예교수', 'Professor Emeritus', 'hmpark@sogang.ac.kr', null, null, null, null, null, null, 'MEDIA_BASE/faculty/0893537001603161166.jpg', null, null, '<h3>학력</h3><ul><li>서울대학교 공학사(1977), Yale University 공학석사 공학박사(1987)</li></ul>', null, true, 4),
  ('오세용', 'Se-Young Oh', '교수', 'Professor', 'syoh@sogang.ac.kr', '02-705-8681', '광전자 나노소재 및 그린에너지 연구실(Photoelectronic Nanomaterial and Green Energy Lab)', 'Photoelectronic Nanomaterial and Green Energy Lab', 'http://advpoly.sogang.ac.kr/advpoly/index.html', 'R', '509A', 'MEDIA_BASE/faculty/0275773001667519339.jpg', 'Organic Photodiode & Photodetector, Perovskite Photovoltaic Cells', '<p class="text-lg font-semibold">Organic Photodiode &amp; Photodetector, Perovskite Photovoltaic Cells</p><p>HIGHLY EFFICIENT AND STABLE PEROVSKITE SOLAR CELLS<br>We are developing solar cells using organic-inorganic hybrids, all inorganic materials, and lead-free perovskite. We are mainly conducting carrier management research using new interface engineering technology to create and commercialize perovskite solar cells with high efficiency and stability.</p><p>ORGANIC BASED PHOTOVOLTAIC CELLS AND PHOTODETECTORS<br>Our laboratory researches organic electronic devices using organic-inorganic hybrid photoactive layers and charges transfer buffer layers. To fabricate high-efficiency organic electronic devices, we are studying the electrical characteristics of micro-interfaces using impedance techniques and the features of nanostructures that affect photoelectric conversion efficiency. We are also developing flexible organic solar cells and photodetectors using Ag transparent electrodes, flexible substrates, and novel buffer layers.</p>', '<h3>학력</h3><ul><li>서강대학교 공학사(1986)</li><li>University of Tsukuba 공학석사(1989)</li><li>University of Tsukuba 공학박사(1993)</li></ul><h3>경력</h3><ul><li>서강대학교 화공생명공학과 교수 (1994~현재)</li><li>미국 Cornell 대학과 일본 동경공업대학 방문교수</li><li>한국공업화학회 편집이사 및 재무이사</li><li>한국고분자학회 평이사</li><li>에너지기술평가원 고급에너지 인력양성사업 단장</li></ul><h3>주요 논문</h3><p>Ga-Eun Lee, Joo Hwan Kim, Jinyoung Kim, Hyun-Seok Cho, Simon MoonGeun Jung, Yuichiro Hayashi, Toshiaki Ito, Kohei Yamaguchi, Yuta Saegusa, Hideaki Takahashi, Hiroshi Sato, Tsutomu Miyasaka, Gyu Min Kim, Se Young Oh, "Interfacial engineering with a carbonyl-functionalized truxene self-assembled monolayer for high efficiency and stable NiOX-based perovskite solar cells." Chemical Engineering Journal (2026): 176106.rn</p><p>Jinyoung Kim, Joo Hwan Kim, Hyun-Seok Cho, Gyu Min Kim, Se Young Oh, "Mechanochemical All-in-Powder Strategy with Intrinsic Additive Incorporation for High-Efficiency and Durable Perovskite Solar Cells" Small (2025), 21.52: e09799.</p><p>Seri Lee, Gyu Min Kim, Tsutomu Miyasaka, Dong-Il Won, Se Young Oh, "Ge-doped Sn-Pb assisted by MACl triple metal cation perovskite solar cells with high open-circuit voltage" Chemical Engineering Journal (2024), 488: 150817.</p><p>Chan Hyuk Ji, Seon-ju Lee, Se-Young Oh, "P3HT-based visible-light organic photodetectors using PEI/PAA multilayers as a p-type buffer layer", RSC advances (2019) 9.64: 37180-37187.</p><p>Seong Bin Lim, Chan Hyuk Ji, Il Soo Oh, Se-Young Oh, "Reduced leakage current and improved performance of an organic photodetector using an ytterbium cathode interlayer", Journal of Materials Chemistry C (2016) 4.22: 4920-4926.</p>', null, false, 18),
  ('최진훈', 'Jinhoon Choi', '교수', 'Professor', 'choi@sogang.ac.kr', '02-705-8917', '뇌 정보학 연구실(Brainformatics Lab)', 'Brainformatics Lab', null, 'R', '609A', 'MEDIA_BASE/faculty/0076789001667519362.jpg', 'Brainformatics', '<p class="text-lg font-semibold">Brainformatics</p><p>The brain is the intelligence center of humans and animals to decide their behaviors. For this, it integrates real time sensory signals from various sensory organs with experiences learned throughout their lives. To understand biological intelligence, we need to know how the brain processes information. Brainformatics is the area of research to understand how the brain encodes and processes information. The brain is studied in a wide spectrum of levels from molecular to social. We mainly study system level computational neuroscience of intelligence manifested through neural networks and individual level behavioral economics of decision and game theories.</p><p>Computational Neuroscience<br>Associative memory: The associative memory is first proposed by Aristotle. We try to understand how the associative memory is stored, recalled, and degraded in the brain using theoretical and computational tools.</p><p>Manifold ways of perception: We are also attacking the problem of manifold ways of perception that allows position, size, direction, distance invariant perception of objects.</p><p>Behavioral Economics<br>Relative decision theory: In the neoclassical economics, psychology of decision was ignored by assuming humans are rational to get a normative theory. However there are many cases where human are not rational but affected by many different factors like emotions Many descriptive decision models were proposed including the prospect theory and the regret theory. However they all have limitations of explaining various non-rational behaviors. We want to develop a new theory of decision making that can explain more than any other models.</p><p>Game theory: Nash equilibrium proposed by John Nash is the central tool in game theory. On the other hand, evolutionary stable equilibrium is also proposed in evolutional game theory where evolution of game strategies through learning is studied. However two concepts are not equivalent. We’d like to develop a new theory that can encompass them.</p>', '<h3>학력</h3><ul><li>서강대학교 공학사(1988)</li><li>University of Missouri-Rolla 공학석사(1990)</li><li>UCLA. 이학석사(1993)</li><li>UCLA. 공학박사(1996)</li></ul><h3>경력</h3><ul><li>교수 (서강대학교, 1997-현재)</li></ul><h3>주요 논문</h3><p>Bomje Woo, Donggyun Shin, Daeryook Yang, Jinhoon Choi, “Reduced model and simulation of neuron with passive dendritic cable: An eigenfunction expansion approach”, Journal of Computational Neuroscience, 19 (2005) 379-397.</p><p>Jinhoon Choi, Kwang Soon Lee “Mixed Constrained Infinite Horizon Linear Quadratic Optimal Control”, Asian Journal of Control, 9 (2003) 412-418.</p><p>Jinhoon Choi, Wook Hyun Kwon, “Continuity and Exponential Stability of Mixed Constrained Model Predictive Control”, SIAM Journal on Control and Optimization, 42 (2003) 839-870.</p><p>Jinhoon Choi, “On the Stabilization of Linear Discrete Time Systems Subject to Input Saturation”, Systems and Control Letters, 36 (1999) 241-244.</p><p>Jinhoon Choi, “Connections Between Local Stability in Lyapunov and Input/Output Senses”, IEEE Tracsactions on Automatic Control, 40 (1995) 2139-2143.</p>', null, false, 17),
  ('이진원', 'Jinwon Lee', '교수', 'Professor', 'jinwonlee@sogang.ac.kr', '02-705-8919', '생물화학공학 연구실(Biochemical Engineering Laboratory)', 'Biochemical Engineering Laboratory', 'http://sgbiochem.sogang.ac.kr', 'R', '513A', 'MEDIA_BASE/faculty/0376878001667519379.jpg', 'Biochemical Engineering, Metabolic Engineering', '<p class="text-lg font-semibold">Biochemical Engineering, Metabolic Engineering</p><p>BIOLOGICAL CONVERSION OF C1 GAS TO USEFUL CHEMICAL<br>C1 gases are representative greenhouse gases that cause global warming but adding carbons to C1 gas creates new carbon chain, which can be a renewable resource. Previous technology using C1 gas has a problem of low economic feasibility compared to petroleum because it requires various processes at high temperature and high pressure. On the other hand, the research of my lab aims to use biocatalysts in order to directly convert C1 gas at low temperature and low pressure.</p><p>In my lab, microbial biocatalysts were developed to convert C1 gas (methane, carbon monoxide) into useful chemicals. This research focuses on the isolation (screening) and improvement of microorganisms capable of converting C1 gas to useful chemicals by using genetic engineering as well as biological process study for efficient conversion of C1 gas with low solubility. Research on converting substances into high value-added biochemicals through additional bioconversion is also progressed.</p>', '<h3>학력</h3><ul><li>Carnegie Mellon University 공학박사(1993)</li></ul><h3>경력</h3><ul><li>Research Associate (University of Virginia, 1993.10-1994.02)</li><li>Professor (Kwangwoon University, 1994.03-2005.02)</li></ul><h3>주요 논문</h3><p>Sukhyeong Cho, Yun Seo Lee, Hanyu Chai, Sang Eun Lim, Jeong Geol Na, Jinwon Lee, “Enhanced production of ectoine from methane using metabolically engineered Methylomicrobium alcaliphilum 20Z”, Biotechnol Biofuels 15, 5(2022)</p><p>Gyo-Yeon Seo, Hoe-Suk Lee, Hyeonsoo Kim, Sukhyeong Cho, Jeong-Geol Na, Young Joo Yeon, Jinwon Lee, “A novel hyperthermophilic methylglyoxal synthase: molecular dynamic analysis on the regional fluctuations”, Sci Rep 11, 2538 (2021)</p><p>Sukhyeong Cho, Seonyoung Ha, Hye Su Kim, Jin Hee Han, Hyeonsoo Kim, Young Joo Yeon, Jeong Geol Na, Jinwon Lee, “Stimulation of cell growth by addition of tungsten in batch culture of a methanotrophic bacterium, Methylomicrobium alcaliphilum 20Z on methane and methanol”, Journal of Biotechnology, 309 (2020), 0168-1656</p><p>Jeongmo Yang, Ji Hee Son, Hyeonsoo Kim, Sukhyeong Cho, Jeong-geol Na, Young Joo Yeon, Jinwon Lee, “Mevalonate production from ethanol by direct conversion through acetyl-CoA using recombinant Pseudomonas putida, a novel biocatalyst for terpenoid production”, Microb Cell Fact 18, 168 (2019)</p><p>Hyeonsoo Kim, Jeongmo Yang, Sukhyeong Cho, Kijun Jeong, Jinbyung Park, Jinwon Lee, “Microbial synthesis of undec-9-enoic acid, heptyl ester from renewable fatty acids using recombinant Corynebacterium glutamicum-based whole-cell biocatalyst”, Process Biochemistry, 66 (2018), 1359-5113</p>', null, false, 16),
  ('오병근', 'Byung-Keun Oh', '교수', 'Professor', 'bkoh@sogang.ac.kr', '02-705-8478', '나노생명공학 연구실(Nanobiotech Lab)', 'Nanobiotech Lab', 'http://nanobiotech.sogang.ac.kr', 'R', '505A', 'MEDIA_BASE/faculty/0559178001667519396.jpg', null, '<p class="text-lg font-semibold">Biosensor platform for medical diagnosis and/or environmental toxin detection</p><p>BIOSENSOR PLATFORM TECHNOLOGY FOR POINT-OF-CARE TESTING<br>The biosensor platform based on microfluidics technology is a compact device with all necessary instrumentation in a portable and easy-to-use format. These devices enable point-of-care testing (POCT) to be performed at patient care sites or environmental sampling sites. POCT devices provide rapid test results with the potential to improve patient care in the medical field. Research activities in the laboratory are focused on development of a platform technology for rapid antigen diagnosis/rapid molecular diagnosis device capable of on-site examination.</p><p>FUNCTIONAL NANO-BIO MATERIALS<br>In the past few years, biomaterial-based nanoparticles with multifunctional properties have received a lot of attention. The fine-tuning ease of nano-biomaterials makes them top candidates for biotechnology applications. Research activities in the laboratory are focused on the design and manufacture of novel nanostructured materials for a wide range of applications including environmental biosensing and medical biosensing. In particular, it focuses on its application to the development of biosensor with high sensitivity.</p>', '<h3>학력</h3><ul><li>서강대학교 공학사   (1995)</li><li>서강대학교 공학석사(1997)</li><li>서강대학교 공학박사(2003)</li></ul><h3>경력</h3><ul><li>Postdoctoral fellow (Northwestern University, 2004-2006)</li><li>Visiting Professor (Auburn University, 2012)</li></ul><h3>주요 논문</h3><p>Myeong-Jun Lee, Eun-Sol Lee, Tae-Hwan Kim, Ju-Won Jeon, YongTae Kim, Byung-Keun Oh, “Detection of thioredoxin-1 using ultra-sensitive ELISA with enzyme-encapsulated human serum albumin nanoparticle”, Nano Convergence 6 (2019) 1-7.</p><p>Jinho Yoon, Taek Lee, Jinhee Jo, Byung-Keun Oh, Jeong-Woo Choi, “Electrochemical H2O2 biosensor composed of myoglobin on MoS2 nanoparticle-graphene oxide hybrid structure”, Biosensors and Bioelectronics 93 (2017) 14-20.</p><p>Jin-Ha Choi, Hai-Jin Hwang, Seung Won Shin, Jeong-Woo Choi, Soong Ho Um, Byung-Keun Oh, “A novel albumin nanocomplex containing both small interfering RNA and gold nanorods for synergetic anticancer therapy” Nanoscale 7 (2015) 9229-9237.</p><p>Jin-Ha Choi, Han Kim, Jae-Hak Choi, Jeong-Woo Choi, Byung-Keun Oh. “Signal Enhancement of Silicon Nanowire-Based Biosensor for Detection of Matrix Metalloproteinase-2 Using DNA-Au Nanoparticle Complexes” ACS applied materials &amp; interfaces 5 (2013) 12023-12028.</p><p>Jin Ha Choi, Hyun Soo Kim, Jeong-Woo Choi, Jong Wook Hong, Young-Kee Kim, Byung-Keun Oh, “A novel Au-nanoparticle biosensor for the rapid and simple detection of PSA using a sequence-specific peptide cleavage reaction” Biosensors and Bioelectronics 49 (2013) 415-419.</p>', null, false, 15),
  ('강태욱', 'Taewook Kang', '교수', 'Professor', 'twkang@sogang.ac.kr', '02-705-8920', '나노플라즈모닉스 연구실(The Nanoplasmonic Research Group)', 'The Nanoplasmonic Research Group', 'https://sites.google.com/view/twkanggroup', 'R', '519A', 'MEDIA_BASE/faculty/0594695001667519412.jpg', 'Nanoplasmonics, Nanophotonics, Biophotonics', '<p class="text-lg font-semibold">Nanoplasmonics, Nanophotonics, Biophotonics</p><p>Development of Novel Plasmonic Sensors and Their Optofluidic Integrated Platforms for Innovative Diagnostics and Environmental Monitoring.<br>Nanoplasmonic sensors have attracted great interests owing to their superior sensing performance. We are interested in the development of novel optofluidic platforms integrated with uniform plasmonic nanostructures for various sensing applications.<br>For example, we are currently working on next-generation optofluidic molecular diagnostic chips to achieve ultrafast amplification of target genes via optical polymerase chain reaction (PCR) by taking advantage of rapid light-to-heat conversion of the plasmonic nanostructures. In addition, we are interested in optofluidic sensing platforms which enable in-situ sensitive monitoring of various biological molecules under complex environments.</p><p>Development and Innovative Biomedical Applications of Artificial Biological Materials by Interfacing with Inorganic Metamaterials.<br>Our group is also interested in the rational design and synthesis of artificial biological materials by mimicking (or enhancing) key functions of their biological counterparts. For example, the electron transport chain (ETC) in mitochondria is essential for maintaining mitochondrial functions. The ETC often becomes dysfunctional due to mitochondrial DNA mutation or reactive oxygen species. We have recently developed artificial electron transfer pathways in the ETC of the mitochondria by interfacing with inorganic metamaterials, which dramatically improve the ETC activity of mitochondria.</p><p>Tailor-made and Large-scale Synthesis and Engineering of Novel Plasmonic Metamaterials and On-demand Printing at Multi-scales.<br>As a chemical engineer, our group are more focusing on the large-scale synthesis and engineering of plasmonic metamaterials. To this end, we have shown that uniform monolayer of plasmonic colloidal nanoparticles assembled at an air-water interface can be an excellent toolbox for on-demand delivery and applications of the plasmonic nanoparticles. For example, we have recently proposed capillary-mediated inverse transfer which allows to print a monolayer of various plasmonic nanoparticles on-demand without applying mechanical forces.</p>', '<h3>학력</h3><ul><li>서울대학교 공학사  (2001)</li><li>서울대학교 공학박사(2006)</li></ul><h3>경력</h3><ul><li>Director, Institute of Integrated Biotechnology, Sogang University (2019-present)</li><li>Professor, Department of Chemical and Biomolecular Engineering, Sogang University (2017-present)</li><li>Trustee of the Korean Institute of Chemical Engineers (2016-present)</li><li>Academic board of the Koreans BioChip Society (2016-present)</li><li>Editor of Journal (NICE) from The Korean Institute of Chemical Engineers (2016-present)</li><li>Editorial Board Member, Scientific Reports (Nature Publishing Group) (2015-present)</li><li>Chair, Department of Chemical and Biomolecular Engineering, Sogang University (2017-2019)</li><li>Visiting Scholar, University of California at Berkeley (2014-2015)</li></ul><h3>주요 논문</h3><p>Yuseung Jo et al., Inner membrane-bound gold nanoparticles as efficient electron transfer mediators for enhanced mitochondrial electron transport chain activity, Nano Letters (2022)</p><p>Keumrai Whang et al., Direct and Precise Determination of Volumetric Mass Transfer Coefficient of Carbon Monoxide for Miniaturized Gas-liquid Reactors via Sensitive Probing of Raman Transitions, Chemical Engineering Journal, 429, 132260 (2022)</p><p>Keumrai Whang et al., Water-wettable Open Plasmonic Nanocavities for Ultrasensitive Molecular Detections in Multiple Phases, Nano Letters, 21 (14), pp 6194-6201 (2021)</p><p>Yonghee Shin et al., Microfluidic Multi-scale Homogeneous Mixing with Uniform Residence Time Distribution for Rapid Production of Various Metal Core–shell Nanoparticles, Advanced Functional Materials, 31, 202007856 (2021)</p><p>Jeehan Chang et al., "Generalized On-demand Production of Nanoparticle Monolayers on Arbitrary Solid Surfaces via Capillarity-Mediated Inverse Transfer, Nano Letters, 19 (3), pp 2074-2083 (2019)</p><p>Jin-Ho Lee et al., General and Programmable Synthesis of Hybrid Liposome/metal Nanoparticles, Science Advances, 2, e1601838 (2016)</p><p>Kihoon Kim et al., Interfacial liquid-state surface-enhanced Raman spectroscopy, Nature Communications, 4, 2182 (2013)</p>', null, false, 14),
  ('조현석', 'Cho, Hyun-Seok', '부교수', 'Associate Professor', 'hscho@sogang.ac.kr', '02-705-8484', '전기화학시스템 연구실 (Electrochemical Systems Lab)', 'Electrochemical Systems Lab', 'https://www.electrochemengrnd.com/', 'R', '507A', 'MEDIA_BASE/faculty/0313050001708478044.jpg', 'Electrochemical engineering, Hydrogen', '<p class="text-lg font-semibold">Electrochemical engineering, Hydrogen</p><p>Electrolyzers, Hydrogen, Fuel cells, Corrosion, Electrochemical systems, Mathematical modeling</p>', '<h3>학력</h3><ul><li>Univ. of South Carolina 공학박사 (2013)</li><li>서강대학교 공학사 (2005)</li></ul><h3>경력</h3><ul><li>책임/선임연구원 (한국에너지기술연구원, 2016-2024)</li><li>책임연구원 (현대자동차, 2015-2016)</li><li>박사후연구원 (University of Alabama, 2013-2015)</li><li>부교수 (과학기술연합대학원, 2022-2024)</li></ul><h3>주요 논문</h3><p>1. M. Mehdi, B. An, H. Kim, S. Lee, C. Lee, M. Seo, M. Noh, W. Cho, C. Kim, C. Choi, B. Kim, M. Kim, and H. Cho*, “Rational Design of a Stable Fe-rich Ni-Fe Layered Double Hydroxide for the Industrially Relevant Dynamic Operation of Alkaline Water Electrolyzers,” Adv. Energy Mater. 13, 2204403(2023).<br>2. C Lee, K. Shin, Y. Park, Y. Yun, M. Kim, W. Cho, C. Kim, H. Lee, S. Lee, G. Henkelman, and H. Cho*, “Catalyst-support interaction in Zr2ON2-supported IrOx electrocatalysts to break the trade-off realationship between the activity and stability in the acidic oxygen evolution reaction,” Adv. Funct. Mater. 33, 2301557 (2023).<br>3. Y. Yun, K. Kim, C. Lee, B. An, J. Kwon, S. Lee, J. Lee, M. Kim, S. Kim, J. Park, B. Kim and H. Cho* “Electrochemical partial reduction of Ni(OH)2 to Ni(OH)2/Ni via coupled oxidation of an interfacing NiAl intermetallic compound for robust hydrogen evolution,” J. Energy Chem. 82, 560 (2023).<br>4. J. Park, K. Ryu, C. Kim, W. Cho, M. Kim, J. Lee, H. Cho*, and J. Lee*, “Green hydrogen to tackle the power curtailment: Meteorological data-based capacity factor and techno-economic analysis” Appl. Energ. 340, 121016(2023).</p>', null, false, 4),
  ('김현철', 'Hyuncheol Kim', '교수', 'Professor', 'hyuncheol@sogang.ac.kr', '02-705-8922', '기능성 나노의학 연구실(Functional Nanomedicine Lab)', 'Functional Nanomedicine Lab', 'https://ddssogang.wixsite.com/biomaterials', 'R', '503A', 'MEDIA_BASE/faculty/0044741001667519454.jpg', 'Functional Nanomedicine', '<p class="text-lg font-semibold">Functional Nanomedicine</p><p>GENE DELIVERY FUNCTIONAL NANOMEDICINES<br>The Functional Nanomedicine Lab is developing nano-delivery system that can effectively deliver gene-based therapeutic drug such as siRNA and mRNA. In general, in order to overcome the limitations of intracellular delivery of nanomedicines such as low efficient endocytosis mechanism, our lab has developed a technology called nano-drill technology that can deliver nanomedicine directly through the cell membrane. The technology demonstrates significantly higher delivery efficiency than general nanomedicines. Using the developed technology, we are developing mRNA vaccines and siRNA-based functional nanomedicines for the treatment of cancer and immune-related diseases.</p><p>NATURAL SUBSTANCES BASED FUNCTIONAL NANOMEDICINE FOR CANCER IMMUNOTHERAPY AND IMMUNE-RELATED DISEASES.<br>The Functional Nanomedicine Lab is developing nanostructures using peptide and protein based natural materials. The developed nanostructures maintain the therapeutic functions of the natural materials; while significantly reducing toxicity and improving stability. The developed natural materials-based nanomedicines are being optimized to be developed as therapeutic agents for cancer and immune-related diseases such as Rheumatoid Arthritis.</p>', '<h3>학력</h3><ul><li>University of Maryland, College Park(2004)</li></ul><h3>경력</h3><ul><li>박사후연구원 (미국립보건원, 2004-2007)</li><li>연구조교수 (듀크의과대학, 2007-2008)</li></ul><h3>주요 논문</h3><p>Yongho Jang, Haemin Kim, Semi Yoon, Hohyeon Lee, Jangsun Hwang, Jaehun Jung, Jin Ho Chang, Jonghoon Choi, Hyuncheol Kim, “Exosome-based photoacoustic imaging guided photodynamic and immunotherapy for the treatment of pancreatic cancer”, J Control Release 330 (2021) 293-304</p><p>Hyounkoo Han, Doyeon Kim, Yongho Jang, Minkyu Seo, Kwangmeyung Kim, Jong Bum Lee, Hyuncheol Kim, “Focused ultrasound-triggered chemo-gene therapy with multifunctional nanocomplex for enhancing therapeutic efficacy”, J Control Release 322 (2020) 346-356</p><p>Doyeon Kim, Jae Hwan Lee, Hyungwon Moon, Minkyu Seo, Hyounkoo Han, Hongkeun Yoo, Howon Seo, Jingu Lee, Sujung Hong, Pilhan Kim, Hak Jong Lee, Jin Wook Chung, Hyuncheol Kim, “Development of evaluation of an ultrasound-triggered microbubble combined transarterial chemoembolization (TACE) formulation on rabbit VX2 liver cancer model”, Theranostics 11 (2021) 79-92</p><p>Hohyeon Lee, Jieun Han, Heejun Shin, Hyounkoo Han, Kun Na, Hyuncheol Kim, “Combination of chemotherapy and photodynamic therapy for cancer treatment with sonoporation effects”, J Control Release 283 (2018) 190-199</p><p>Doyeon Kim, Suhyun Park, Hongkeun Yoo, Suhyeon Park, Jeewon Kim, Kyuhee Yum, Kwangmeyung Kim, Hyuncheol Kim, “Overcoming anticancer resistance by photodynamic therapy-related efflux pump deactivation and ultrasound-mediated improved drug delivery efficiency, Nano Converg 7 (2022) 30</p><p>Hohyeon Lee, Yongho Jang, Suhyun Park, Hyejin Jang, Eun-Joo Park, Hyun Jung Kim, Hyuncheol Kim, “ Development and evaluation of a CEACAM6-targeting theranostic nanomedicine for photoacoustic-based diagnosis and chemotherapy of metastatic cancer”, Theranostics 8 (2018) 4247-4261</p>', null, false, 13),
  ('김충익', 'Choongik Kim', '교수', 'Professor', 'choongik@sogang.ac.kr', '02-705-7964', '하이브리드 전자재료 연구실 (Hybrid Electronic Materials Laboratory)', 'Hybrid Electronic Materials Laboratory', 'https://sites.google.com/view/ckimlab/home', 'R', '605A', 'MEDIA_BASE/faculty/0648763001480566548.jpg', 'Organic', '<p class="text-lg font-semibold">Organic/inorganic hybrid electronic materials for optoelectronics</p><p>STRESS-RESISTANT ELECTRONIC MATERIALS AND DEVICES<br>New radiation- or bias-stress resistant materials including metal oxides and organic/inorganic hybrids for mission- or safe-critical applications (e.g. nano-scaled semiconductor circuits, space exploration, nuclear energy, and medical technology).</p><p>GREEN PROCESS FOR ORGANIC OPELECTRONIC DEVICES<br>Green (eco-friendly) materials and processes for the fabrication of organic optoelectronic devices. Exploration of a wide range of green solvents to process organic semiconductor layers for enhanced electrical performance and stability.</p><p>POLYELECTROLYTES FOR LITHIUM ION BATTERIES<br>New solid polyelectrolyte precursors for the gelation by radiation-induced polymerization for lithium ion batteries.</p>', '<h3>학력</h3><ul><li>서울대학교 이학사(2003)</li><li>Northwestern University 이학박사(2009)</li></ul><h3>경력</h3><ul><li>서강대학교 화공생명공학과 교수 (2011-현재)</li><li>하버드대학교 박사후연구원 (2009-2010)</li></ul><h3>주요 논문</h3><p>S. Yoon, Y. Kim, D. Ho, J. Kim, H. Kim, O. Marconi, A. Marrocchi, C. Kim, “Brewers’ Spent Grain (BSG)-Based Green Dielectric Materials for Low-Voltage Operating Solution-Processed Organic Field-Effect Transistors”, Journal of Materials Chemistry C (2022) in press.</p><p>Y. Lee, D. Ho, F. Valentini, T. Earmme, A. Marrocchi, L. Vaccaro, C. Kim, “Improving Charge Transport Performance of Solution-Processed Organic Field-Effect Transistors Using Green Solvent Additives”, Journal of Materials Chemistry C 9 (2021) 16506.</p><p>D. Ho, H-Y. Jeong, Le Minh, H. Usta, H. I. Kwon, M.-G. Kim, C. Kim, "Microstructural Modulation of Organic Passivation Layers for Metal Oxide Semiconductors to Achieve High Bias Stability", Journal of Materials Chemistry C 8 (2020) 11209.</p><p>Y. Park, K. Baek, C. Kim, "Solution-Processed Non-Volatile Organic Transistor Memory based on Semiconductor Blends", ACS Applied Materials and Interfaces 11 (2019) 8327.</p><p>B. Park, D. Ho, G. Kwon, S. Y. Seo, C. Kim, M. G. Kim, "Solution-Processed Rad-hard Amorphous Metal-Oxide Thin-Film Transistors", Advanced Functional Materials 28 (2018) 1802717.</p><p>G. Kwon, K.-T. Kim, B. D. Choi, C. H. Lee, Y.-Y. Noh, S.Y. Seo, C. Kim, M.-G. Kim, "Multifunctional Organic-Semiconductor Interfacial Layers for Solution-Processed Oxide-Semiconductor Thin-Film Transistor”, Advanced Materials 29 (2017) 1607055.</p>', null, false, 12),
  ('하경수', 'Kyoung-Su Ha', '교수', 'Professor', 'philoseus@sogang.ac.kr', '02-3274-4892', '지속가능 탄소중립 연구실 (Carbon Neutral Laboratory for Sustainability)', 'Carbon Neutral Laboratory for Sustainability Lab', 'https://sites.google.com/view/kshalab', 'R', '515A', 'MEDIA_BASE/faculty/0742157001723599017.jpg', 'Catalysis for Eco-friendly Energy', '<p class="text-lg font-semibold">Catalysis for Eco-friendly Energy</p><p>HIGHLY EFFICIENT HETEROGENEOUS CATALYSTS AND DESIGN OF COMPACT REACTORS<br>The preparation of ordered mesoporous heterogeneous catalysts by sol-gel or nano-casting method and the synthesis of nanosized materials are of our interest to develop efficient heterogeneous catalytic systems. In addition, conventional reaction systems such as lab-scale fixed bed reactor, stirred tank reactor and novel micro-structured reactor are designed and applied for further application of compact chemical process design as well. Development of reaction kinetics is also one of main research parts for the development of efficient integrated chemical processes.<br>FUELS FROM ALTERNATIVE FEEDSTOCKS AND DEVELOPMENT OF ENVIRONMENTALLY-BENIGN PROCESSES<br>The efficient utilizations of natural (shale) gases have been receiving enormous interest as an alternative feedstock. C1 chemistry is one of the important methodologies for producing clean fuels and chemicals using heterogeneous catalysts. In our laboratory, the synthesis of alcohols, hydrocarbons and chemical intermediates from syngas has been investigated using ordered mesoporous catalysts through some novel preparation routes such as sol-gel, nano-casting or nano-sized material synthesis. Efficient conversion of biomass into useful chemicals and fuels has been studied via catalytic conversion routes. The application of micro-structured reactors has been our research topics for the development of compact chemical processes.</p>', '<h3>학력</h3><ul><li>서울대학교 공학사   (1995)</li><li>서울대학교 공학박사 (2001)</li></ul><h3>경력</h3><ul><li>Principal Investigator (Korea Research Institute of Chemical Technology, 2009 – 2014)</li><li>Team Leader (LG Chem Research Park, 2001 – 2009)</li></ul><h3>주요 논문</h3><p>Dong Hyeon Kim1,†, Hee Hwan Kim1,†, Juchan Kim1, Youngchang Byun2,*, and Kyoung-Su Ha1,*, Recovery of methyl methacrylate from waste poly (methyl methacrylate) pellets using a low-temperature plasma and zeolites, Chemical Engineering Journal, accepted, 2024. https://doi.org/10.1016/j.cej.2024.154438<br>Wonho Jung, Jinwon Lee*, and Kyoung-Su Ha*, A Combined Production Technology for Ethylene and Hydrogen with an Ethane Cracking Center and Dielectric Barrier Discharge Plasma Reactor, Chemical Engineering Journal 462 (2023) 142155. https://doi.org/10.1016/j.cej.2023.142155<br>Wonho Jung, Jinwon Lee*, Kyoung-Su Ha*, Ethylene Production Processes in a Carbon-Neutral Strategy, Energy Conversion and Management, 311 (2024) 118462. https://doi.org/10.1016/j.enconman.2024.118462<br>Juchan Kim, Jaekwon Jeoung, Jonghyun Jeon, Jip Kim, Young Sun Mok, Kyoung-Su Ha*, Effects of dielectric particles on non-oxidative coupling of methane in a dielectric barrier discharge plasma reactor, Chemical Engineering Journal 377 (2019) 119896-119908. https://doi.org/10.1016/j.cej.2018.09.057<br>Daegak Kim, Gyung-Ah Park, Jemi Lim, Kyoung-Su Ha*, Effects of spatially restricted Ni nanocrystals within ordered mesopores on the production of syngas, Chemical Engineering Journal 316 (2017) 1011-1025. https://doi.org/10.1016/j.cej.2017.02.014<br>Jongkook Hwang†, Geunjae Kwak†, Yun-Jo Lee, Yong Tae Kim, Inyoung Jeong, Seongseop Kim, Ki-Won Jun*, Kyoung-Su Ha*, Jinwoo Lee*, Direct confinement of Ru nanoparticles inside nanochannels of large pore mesoporous aluminosilicate for Fischer–Tropsch synthesis, Journal of Materials Chemistry A 3 (2015) 23725-23731. https://doi.org/10.1039/C5TA06184A<br>Kyoung-Su Ha*, Geunjae Kwak, Ki-Won Jun, Jongkook Hwang, Jinwoo Lee*, Ordered mesoporous carbon nanochannel reactors for high-performance Fischer–Tropsch synthesis, Chemical Communications 49 (2013) 5141-5143. https://doi.org/10.1039/C3CC00297G</p>', null, false, 11),
  ('이종석', 'Jong Suk Lee', '교수', 'Professor', 'jongslee@sogang.ac.kr', '02-705-8496', '녹색지속가능분리 연구실 (Green & Sustainable Separation Laboratory)', 'Green & Sustainable Separation Laboratory', 'http://gsslab.sogang.ac.kr/', 'R', '409A', 'MEDIA_BASE/faculty/0156100001480567148.jpg', 'Membranes, Sorbents, Barriers', '<p class="text-lg font-semibold">Membranes, Sorbents, Barriers</p><p>1) Mixed matrix membranes for olefin/paraffin separations<br>Olefin/paraffin separation is one of the most important processes in the petrochemical industry due to the highly utile applications of those gases in our everyday life. Propylene is the second most important feedstock next to ethylene with its annually increasing demands: the 90 million tons of global demand in 2014 was expected to continually increase, exceeding 130 million tons in 2023 based on IHS Chemical North American Propylene Supply Study. Currently, propylene/propane (i.e., C3H6/C3H8) separation is implemented mainly by highly energy-intensive cryogenic distillation due to the similar physical properties between C3H6 and C3H8 (i.e., Tb of C3H6 and C3H8 is -47.6 ℃ and -42.1 ℃, respectively). Membrane-based separation technique is promising due to its good energy efficiency as well as low capital cost. Conventional polymeric membranes, however, have been yet to reach and/or surpass the performance limit so-called “the upper bound”, albeit their great advantage of high processability. Mixed matrix membranes (MMMs) are essentially hybrid membranes consisting of inorganic molecular sieves (dispersed phase) and polymeric matrix (continuous phase). Our recent work is focused on engineering the structure of zeolitic imidazolate frameworks-8 (ZIF-8) and polymer matrix for enhanced C3H6/C3H8 separation performance.</p><p>2) Carbon molecular sieve membranes for natural gas processing<br>Natural gas processing is one of the largest industrial applications of gas separation membranes. Carbon dioxide (CO2), a common impurity in natural gas, should be removed to a level of &lt; 2% based on the U.S. gas pipeline specification in order to minimize corrosion of the pipeline as well as to obtain high heating value. Also, some low-quality natural gas reserves must undergo a nitrogen rejection process to satisfy pipeline specifications which require that the total concentration of inert gases be less than 4%. Membrane technology is promising due to its good energy efficiency and small footprint; however, it requires highly delicate molecular level engineering to improve separation efficiency as well as high pressure CO2-induced plasticization resistance. Carbon molecular sieve (CMS) membranes are a promising candidate for natural gas processing due to their peculiar pore structure-induced excellent separation performance. Recently, our group reported a simple and effective method of fabricating high-performance CMS hollow fiber membranes with excellent CO2/CH4 separation performance by pyrolysis of rigid double-stranded siloxane containing precursors [1]. Also, we developed CMS membranes with excellent N2/CH4 separation performance and identified the effect of SiOx phase on enhanced N2/CH4 separation performance.</p><p>3) Biomimetic patterning of polymeric membranes for enhanced anti-biofouling performance<br>Surface contamination by biological matter, so-called biofouling, is a persistent problem for materials that are exposed to aquatic environments because it degrades the materials’ function and performance efficiency. Specifically, most polymeric membranes for water treatment suffer from serious performance deterioration by biofouling, which reduces the operating efficiency of the membrane process. Recently, we demonstrated that the Sharkskin-mimetic patterns can significantly suppress the biofouling of desalination membranes and identified the anti-biofouling mechanism of topologically surface modified membranes. We are engineering the surface topology and chemical structure of polymeric membranes for enhanced long-term separation performance.</p>', '<h3>학력</h3><ul><li>Ph.D.,Georgia Institute of Technology(2011)</li></ul><h3>경력</h3><ul><li>Editorial Board Member (Journal of the Taiwan Institute of Chemical Engineers, 2023 – Present)</li><li>Visiting Scholar (University of California, Berkeley, 2022 – 2023)</li><li>Associate Editor (Korean Journal of Chemical Engineering, 2021 – Present)</li><li>Senior Research Scientist (Korea Institute of Science and Technology, 2012 – 2016)</li><li>Post-doc (Georgia Institute of Technology, 2011 – 2012)</li></ul><h3>주요 논문</h3><p>Ki Jin Nam, Hyun Jung Yu, Seungho Yu, Jeongho Seong, Seok-Jhin Kim, Ki Chul Kim, Jong Suk Lee, In situ synthesis of multivariate zeolitic imidazolate frameworks for C2H4/C2H6 kinetic separation, Small Methods 6 (2022) 2200772 rn(https://www.youtube.com/watch?v=fQzEhyBBV5w)<br>Heseong An, Kie Yong Cho, Seungho Yu, Ki Chul Kim, Ju Ho Shin, Ki Jin Nam, Jung Hoon Park, Jong Suk Lee, Triple-ligand zeolitic imidazolate frameworks for highly CO2 selective mixed matrix membranes, Chemical Engineering Journal 433 (2022) 133606<br>Heseong An, Kie Yong Cho, Qiang Lyu, Da-Shiuan Chiou, Ki Jin Nam, Dun-Yen Kang, Li-Chiang Lin, Jong Suk Lee, Facile defect engineering of zeolitic imidazolate frameworks towards enhanced C3H6/C3H8 separation performance, Advanced Functional Materials (2021) 2105577 (https://v.daum.net/v/20210907120016609)<br>Wonho Jung, Sunghyun Park, Kwang Soon Lee, Jae-Deok Jeon, Hyung Keun Lee, Jeong-Hoon Kim, Jong Suk Lee, Rapid thermal swing adsorption process in multi-beds scale with sensible heat recovery for continuous energy-efficient CO2 capture, Chemical Engineering Journal 392 (2020) 123656<br>Wansuk Choi, Changhoon Lee, Dahye Lee, Young June Won, Gi Wook Lee, Min Gyu Shin, Byoungjin Chun, Taek-Seung Kim, Hee-Deung Park, Hyun Wook Jung, Jong Suk Lee, Jung-Hyun Lee, Sharkskin-mimetic desalination membranes with ultralow biofouling, Journal of Materials Chemistry A 6 (2018) 23034-23045</p>', null, false, 10),
  ('이원홍', 'Won Hong Lee', '명예교수', 'Professor Emeritus', 'wonlee123hong@hanmail.net', null, null, null, null, null, null, 'MEDIA_BASE/faculty/0079663001480567271.jpg', null, null, '<h3>학력</h3><ul><li>Michigan State University 공학박사(1975)</li></ul>', null, true, 10),
  ('최청송', 'Chung Song choi', '명예교수', 'Professor Emeritus', 'cschoi@sogang.ac.kr', null, null, null, null, null, null, 'MEDIA_BASE/faculty/0876971001480567286.jpg', null, null, '<h3>학력</h3><ul><li>고려대학교 화학공학과 공학박사(1974)</li></ul>', null, true, 9),
  ('박형상', 'Hyung Sang Park', '명예교수', 'Professor Emeritus', 'hspark@sogang.ac.kr', null, null, null, null, null, null, 'MEDIA_BASE/faculty/0212277001480567344.jpg', null, null, '<h3>학력</h3><ul><li>Institute National Polytechnique de Toulouse 공학박사(1982)</li></ul>', null, true, 8),
  ('나정걸', 'Jeong Geol Na', '교수', 'Professor', 'narosu@sogang.ac.kr', '02-705-7955', '생물공정 연구실(Bioprocess Engineering Lab)', 'Bioprocess Engineering Laboratory', 'https://bplsogang.bio', 'R', '511', 'MEDIA_BASE/faculty/0679901001667519540.jpg', 'Bioprocess engineering', '<p class="text-lg font-semibold">Bioprocess engineering</p><p>DESIGN AND OPTIMIZATION OF BIOPROCESS WITH MULTI-SCALE FEATURES<br>Bioprocess has a multi-scale characteristic involving intracellular metabolic networks, cell-to-cell interactions, and spatiotemporal effects within bioreactors. These effects influence each other and eventually determine the performance of the process. Our research objective is to analyze these complicated behaviors in bioreactors with microbial cells and design and optimize novel systems based on the quantitative description of the process. We perform research, including monitoring critical metabolites in the cells, off-gas analysis, kinetic modeling, reactor design, and scale-down approach. Through these efforts, microbial fermentation, regarded as art, would be a core part of biotechnology.rn<br>BIOPROCESS DEVELOPMENT FOR C1 GAS CONVERSION FOR NET ZERO FUTURE<br>A carbon neutral society is a crucial agenda facing humanity today. Amid net-zero push, biological C1 gas conversion using biocatalysts could be a promising option for mitigating greenhouse gas emission and producing green chemicals. On the other hand, biological gas conversion is an interesting system in which there remain engineering issues to address. The poor mass transfer properties of gaseous substrates into culture broth limit carbon flux towards target products inside cells, thus restricting the productivity improvement. Also, the three-phase behavior of substrates (gas), culture medium (liquid), and cells (solids) makes mathematical analyses difficult. We are attempting to optimize biological gas conversion system using the abovementioned tools, ultimately contributing to a net-zero society establishment.</p>', '<h3>학력</h3><ul><li>KAIST 화학공학 박사(2001)</li></ul><h3>경력</h3><ul><li>한국에너지기술연구원 선임/책임연구원 (2004 – 2016)</li><li>한국에너지기술연구원 바이오자원순환연구실장 (2013-2016)</li></ul><h3>주요 논문</h3><p>Eungsu Kang, Eunjoo Moon, Wooho Song, Lyul Ho Kim, Ji Sung Hyung, Jae-Hwan Jo, Jeong-Ho Park, Min-Sik Kim, Jeong-Geol Na, Yoo Seong Choi, “Chitosan/oleamide nanofluid as a significant medium for enhancing gas utilization efficiency in C1-gas microbial biotransformation”, Chemical Engineering Journal 433 (2022) 133846.</p><p>Seo Young Jo, Jina Son, Yu Jung Sohn, Seo Hyun Lim, Ji Yeon Lee, Jee in Yoo, Se Young Park, Jeong-Geol Na, Si Jae Park, “A shortcut to carbon-neutral bioplastic production: Recent advances in microbial production of polyhydroxyalkanoates from C1 resources”, International Journal of Biological Macromolecules 192 (2021) 978-998.</p><p>Tae Uk Khang, Min-Jae Kim, Jee In Yoo, Yu Jung Sohn, Sang Goo Jeon, Si Jae Park, Jeong-Geol Na, “Rapid analysis of polyhydroxyalkanoate contents and its monomer compositions by pyrolysis-gas chromatography combined with mass spectrometry (Py-GC/MS)”, International Journal of Biological Macromolecules 174 (2021) 449-456.</p><p>Diep Thi Ngoc Nguyen, Ok Kyung Lee, Chaeil Lim, Jinwon Lee, Jeong-Geol Na, Eun Yeol Lee, “Metabolic engineering of type II methanotroph, Methylosinus trichosporium OB3b, for production of 3-hydroxypropionic acid from methane via a malonyl-CoA reductase-dependent pathway”, Metabolic Engineering 59 (2020) 142-150.</p><p>Min-Sik Kim, Myounghoon Moon, Hana Nur Fitriana, Jin-Suk Lee, Jeong-Geol Na, Gwon Woo Park, “Pressurized cultivation strategies for improved microbial hydrogen production by Thermococcus onnurineus NA1”, Bioprocess and Biosystems Engineering 43 (2020) 1119-1122.</p>', null, false, 9),
  ('이희우', 'Hee-Woo Rhee', '명예교수', 'Professor Emeritus', 'hwrhee@sogang.ac.kr', null, null, null, null, null, null, 'MEDIA_BASE/faculty/0041899001603161345.jpg', null, null, '<h3>학력</h3><ul><li>서울대학교 공학사(1978), 한국과학기술원 공학석사(1980), The University of Connecticut 공학박사(1987)</li></ul>', null, true, 3),
  ('이광순', 'Kwang Soon Lee', '명예교수', 'Professor Emeritus', 'kslee@sogang.ac.kr', null, null, null, null, null, null, 'MEDIA_BASE/faculty/0164682001603161047.jpg', null, null, '<h3>학력</h3><ul><li>한국과학기술원 공학박사(1983)</li></ul>', null, true, 5),
  ('이재욱', 'Jae Wook Lee', '명예교수', 'Professor Emeritus', 'jwlee@sogang.ac.kr', null, null, null, null, null, null, 'MEDIA_BASE/faculty/0093593001488957088.jpg', null, null, '<h3>학력</h3><ul><li>서울대학교 공학박사(1981)</li></ul>', null, true, 7),
  ('강문성', 'Moon Sung Kang', '교수', 'Professor', 'kangms@sogang.ac.kr', '02-705-8475', '전자 및 이온소재 연구실 (Electronic & Ionic Materials Engineering Laboratory)', 'Electronic & Ionic Materials Engineering Laboratory', 'https://sites.google.com/view/mskanggroup', 'R', '611A', 'MEDIA_BASE/faculty/0680161001733812771.jpg', null, '<p class="text-lg font-semibold">Semiconductors and Display Materials.</p><p>Our research focus is on electronic materials such as quantum dots, semiconductor nanocrystals, organic semiconductors, and even electrolyte. We are interested in i) understanding physical properties of these materials including light emission/absorption characteristics, electrical/ionic transport characteristics, and electronic properties ii) developing processing methods for practical applications of these materials in semiconductor and display industry. rnrn High resolution patterning of quantum dots (QDs) – 양자점 초고해상도 패터닝 공정 개발rn Electrical transport characteristics of semiconductor nanocrystals – 나노반도체의 전기전도 특성 이해rn High resolution patterning of OLED materials – OLED 소재의 고해상도 패터닝 공정 개발 rn QD-LEDs and OLEDs – 양자점 발광소자 및 유기 발광소자rn Electrochemistry and electrochemiluminescence 전기화학 및 전기화학발광rn UV-crosslinkable materials - UV 경화형 소재</p>', '<h3>학력</h3><ul><li>서울대학교 공학사 (2006)</li><li>University of Minnesota 공학박사(2011)</li></ul><h3>경력</h3><ul><li>Associate/assistant professor, Soongsil University, Korea (2012-2018)</li><li>Postdoctoral researcher, Seoul National University, Korea (2011)</li></ul><h3>주요 논문</h3><p> Direct Patterning of Colloidal Quantum Dots with Adaptable Dual-Ligand Surface - Nature Nanotechnology 2022rn Nondestructive Photopatterning of Heavy-Metal-Free Quantum Dots - Advanced Materials 2022rn Visco-Poroelastic Electrochemiluminescence Skin with Piezo-Ionic Effect - Advanced Materials 2021 rn High-resolution Pattering of Colloidal Quantum Dots via Non-destructive, Light-driven Ligand Crosslinking - Nature Communications 2020rn Universal Three-Dimensional Crosslinker for All-Photopatterned Electronics - Nature Communications 2020rn Light-emitting Devices Based on Electrochemiluminescence Gels - Advanced Functional Materials 2020 rn Universal Route to Impart Orthogonality to Polymer Semiconductors for Submicron Tandem Electronics - Advanced Materials 2019rn Electrically Controllable Molecularization of Terahertz Meta-Atoms - Advanced Materials 2018rn Lead-Free Perovskite Nanocrystals for Light-Emitting Devices – The Journal of Physical Chemistry Letters 2018rn Light-Emitting Devices Based on Electrochemiluminescence: Comparison to Traditional Light-Emitting Electrochemical Cells – ACS Photonics 2018</p>', null, false, 8),
  ('김형준', 'Hyeong Jun Kim', '부교수', 'Associate Professor', 'hjunkim@sogang.ac.kr', '02-705-8483', '고분자 이온 소재 연구실 (Polymer Ionic Materials Laboratory)', 'Polymer Ionic Materials Laboratory', 'http://www.hjunkim-lab.com', 'R', '607A', 'MEDIA_BASE/faculty/0482994001667519578.jpg', null, '<p class="text-lg font-semibold">Charged Polymer Materials and Devices</p><p>PHYSICOCHEMICAL BEHAVIORS OF CHARGED POLYMERS<br>Charged polymers are everywhere! From biological macromolecules to synthetic polyelectrolytes for today''s leading technologies, charged macromolecules are fundamental elements of our life. Our team is engaged in exploring the physicochemical and biological phenomena of charged macromolecules as well as their applications in new functional devices. Our research aims to expand our understanding of charged macromolecules and translate their activities into soft and highly deformable functional devices.</p><p>IONOTRONICS DEVICE – IONIC DIODE, TRANSISTORS, ELECTRO-ADHESION, SENSORS<br>Soft solids capable of conducting ions offer promise for the design of entirely new classes of highly deformable and bio-inspired devices. We demonstrate that the junction of two oppositely charged polymer yields an ‘ionic double layer’, analogous to the depletion layer in a semiconducting p-n junction. This enables the design of ionic devices for rectifying and switching non-Faradaic ionic currents. Furthermore, soft and stretchable polyelectrolyte junctions provide fundamentally new functionalities including low voltage reversible electro-adhesion and electro-mechanical transduction,</p>', '<h3>학력</h3><ul><li>KAIST 공학사   (2011)</li><li>KAIST 공학박사 (2017)</li></ul><h3>경력</h3><ul><li>박사후 연구원 (Dept. of Polymer Science and Engineering, University of Massachusetts Amherst,  2017-2020)</li><li>서강대학교 화공생명공학과 조교수 (2021-현재)</li></ul><h3>주요 논문</h3><p>Hyeong Jun Kim, Lindsay Paquin, Christopher W. Barney, Soonyong So, Baohong Chen, Zhigang Suo*, Alfred J. Crosby*, and Ryan C. Hayward* "Low-Voltage Reversible Electro-Adhesion of Ionoelastomer Junctions" Advanced Materials, 32 (2020) 2000600<br>Hyeong Jun Kim, Baohong Chen, Zhigang Suo*, and Ryan C. Hayward* "Ionoelastomer Junctions Between Polymer Networks of Fixed Anions and Cations" Science, 367 (2020) 773</p>', null, false, 7),
  ('류재건', 'Jaegeon Ryu', '부교수', 'Associate Professor', 'jryu@sogang.ac.kr', '02-705-8482', '에너지 저장 소재 및 시스템 연구실 (Battery Energy Engineering Lab)', 'Battery Energy Engineering Lab', 'https://jaegeonryu.owlstown.net/', 'R', '517A', 'MEDIA_BASE/faculty/0483865001667519603.jpg', 'Energy Storage Materials & Systems', '<p class="text-lg font-semibold">Energy Storage Materials &amp; Systems</p><p>DEVELOPMENTS OF HIGH-ENERGY-DENSITY RECHARGEABLE BATTERIES<br>Traditional rechargeable batteries have already reached the limitation of electrochemical performances in terms of both energy and power density. Utilizing advanced electrochemistry and materials chemistry, our research group develops energy-dense electrode host materials, negative electrodes in particular which range from practical to next-generation materials, based on molecular-scale design to address their chronic issues such as dimensional collapse and low electrical conductivity. This can be achieved by specimen-level (structure or interface engineering of host) and/or electrode-level (multi-functional polymeric binders or polymeric separator membranes). By integrating novel electrode components, we aim at developing advanced (and/or beyond Li) rechargeable batteries with high-energy density and fast-charging capability for electrified applications.</p><p>MULTIMODAL OPERANDO (IN-SITU) ANALYSIS OF ELECTROCHEMICAL REACTIONS<br>The complexity of interface or bulk electrochemical reactions during battery operation has posed a significant challenge for battery scientists to take the next step toward the development of next-generation battery materials. In our group, multimodal operando or in-situ analysis of battery materials has been studied to obtain an insight into the design rationale for advanced battery development. Multi-scale spectroscopy analysis is expected to provide near-surface electrolyte solvation structure, intermediate speciation of electrolyte, charge-transport mechanism, and electrochemical reversibility while microscopy analysis provides structural change, charge storage mechanism, and electro-mechanical information.</p>', '<h3>학력</h3><ul><li>UNIST 공학사   (2013)</li><li>UNIST 공학박사 (2018)</li></ul><h3>경력</h3><ul><li>2018-2020, 박사후 연구원(포항공과대학교)</li><li>2020-2022, 박사후 연구원(Pacific Northwest National Laboratory)</li></ul><h3>주요 논문</h3><p>Jieun Kang, Dong-Yeob Han, Sungho Kim, Jaegeon Ryu*, Soojin Park*, “Multiscale Polymeric Materials for Advanced Lithium Battery Applications”, Advanced Materials 34 (2022) 2203194.</p><p>Jaegeon Ryu†*, Dong-Yeob Han†, Dongki Hong, Soojin Park*, “A Polymeric Separator Membrane with Chemoresistance and High Li-ion Flux for High-Energy-Density Lithium Metal Batteries”, Energy Storage Materials 45 (2022) 941-951.</p><p>Jaegeon Ryu†, Taesoo Bok†, Se Hun Joo†, Seokkeun Yoo, Gyujin Song, Su Hwan Kim, Sungho Choi, Hu Young Jeong, Min Gyu Kim, Seok Ju Kang, Chongmin Wang*, Sang Kyu Kwak*, Soojin Park*, “Electrochemical Scissoring of Disordered Silicon-Carbon Composites for High-Performance Lithium Storage”, Energy Storage Materials 36 (2021) 139-146.</p><p>Jaegeon Ryu†, Sungho Kim†, Jimin Kim†, Sooham Park, Seungho Lee, Seokkeun Yoo, Jangbae Kim, Nam-Soon Choi, Ja-Hyoung Ryu*, Soojin Park*, “Room-Temperature Cross-Linkable Natural Polymer Binder for High-Rate and Stable Silicon Anode”, Advanced Functional Materials 30 (2020) 1908433.</p><p>Onur Buyukcakir†*, Jaegeon Ryu†, Se Hun Joo†, Jieun Kang, Recep Yuksel, Jiyun Lee, Yi Jiang, Sungho Choi, Sun Hwa Lee, Sang Kyu Kwak*, Soojin Park*, Rodney S. Ruoff*, “Lithium Accommodation in a Redox-Active Covalent Triazine Framework for High Areal Capacity and Fast-Charging Lithium-Ion Batteries”, Advanced Functional Materials 30 (2020) 2003761</p><p>Jaegeon Ryu†, Ji Hui Seo†, Gyujin Song, Keunho Choi, Dongki Hong, Chongmin Wang, Hosik Lee, Jun Hee Lee*, Soojin Park*, “Infinitesimal Sulfur Fusion Yields Quasi-Metallic Bulk Silicon for Stable and Fast Energy Storage”, Nature Communications 10 (2019) 2351.</p><p>Jaegeon Ryu†, Tianwu Chen†, Taesoo Bok†, Gyujin Song, Jiyoung Ma, Chihyun Hwang, Langli Luo, Hyun-Kon Song, Jaephil Cho, Chongmin Wang*, Sulin Zhang*, Soojin Park*, “Mechanical Mismatch-Driven Rippling in Carbon-Coated Silicon Sheets for Stress-Resilient Battery Anodes”, Nature Communications 9 (2018) 2924.</p>', null, false, 6),
  ('박제영', 'Jeyoung Park', '부교수', 'Associate Professor', 'jeypark@sogang.ac.kr', '02-705-8477', '지속가능 플라스틱 연구실 (Sustainable Plastics Lab)', 'Sustainable Plastics Lab', 'https://jeypark.owlstown.net/', 'F', '705', 'MEDIA_BASE/faculty/0259732001667519621.jpg', 'Sustainable Plastics', '<p class="text-lg font-semibold">Sustainable Plastics</p><p>It has been 100 years in macromolecular chemistry since the first concept of macromolecules consisting of a large number of repeating units in 1920. Polymer science and plastic industry have been developed rapidly, producing 400 million tons per year, yet current recycling rate is only 9%. In 2050, the proportion of plastics in total carbon emission is expected to reach 15%, so research attentions to sustainable polymers are urgent.</p><p>For the next 100 years of polymers and plastics, our research group focuses on the sustainability from the design of novel chemical structure, polymerization, biodegradation, and to the applications related to carbon neutrality considering end-of-life.</p><p>Sustainable ideas to realization: for examples, tough-yet-biodegradable disposable bags; marine-degradable microplastics; high-performance nanocellulose-composites; recyclable thermosets; up-cycling of current plastics; zero-burden new polymer structures.</p>', '<h3>학력</h3><ul><li>KAIST 이학사  (2007)</li><li>KAIST 이학박사(2012)</li></ul><h3>경력</h3><ul><li>책임연구원 (한국화학연구원, 2014-2022)</li><li>겸직교수 (포항공대, 2020-2022)</li><li>부교수 (과학기술연합대학원대학교, 2016-2022)</li><li>연구원 (SK이노베이션, 2012-2014)</li></ul><h3>주요 논문</h3><p>Sungbin Ju, Giyoung Shin, Minkyung Lee, Jun Mo Koo, Hyeonyeol Jeon, Yong Sik Ok, Dong Soo Hwang, Sung Yeon Hwang, Dongyeop X Oh, Jeyoung Park, “Biodegradable chito-beads replacing non-biodegradable microplastics for cosmetics”, Green Chemistry 23 (2021) 6953-6965.</p><p>Hyeri Kim, Hyeonyeol Jeon, Giyoung Shin, Minkyung Lee, Jonggeon Jegal, Sung Yeon Hwang, Dongyeop X Oh, Jun Mo Koo, Youngho Eom, Jeyoung Park, “Biodegradable nanocomposite of poly (ester-co-carbonate) and cellulose nanocrystals for tough tear-resistant disposable bags”, Green Chemistry 23 (2021) 2293-2299.</p><p>Seul-A Park, Youngho Eom, Hyeonyeol Jeon, Jun Mo Koo, Eun Seong Lee, Jonggeon Jegal, Sung Yeon Hwang, Dongyeop X Oh, Jeyoung Park, “Preparation of synergistically reinforced transparent bio-polycarbonate nanocomposites with highly dispersed cellulose nanocrystals”, Green Chemistry 21 (2019) 5212-5221.</p><p>Seul-A Park, Hyeonyeol Jeon, Hyungjun Kim, Sung-Ho Shin, Seunghwan Choy, Dong Soo Hwang, Jun Mo Koo, Jonggeon Jegal, Sung Yeon Hwang, Jeyoung Park, Dongyeop X Oh, “Sustainable and recyclable super engineering thermoplastic from biorenewable monomer”, Nature Communications 10 (2019) 2601.</p><p>Seon‐Mi Kim, Hyeonyeol Jeon, Sung‐Ho Shin, Seul‐A Park, Jonggeon Jegal, Sung Yeon Hwang, Dongyeop X Oh, Jeyoung Park, “Superior toughness and fast self‐healing at room temperature engineered by transparent elastomers”, Advanced Materials 30 (2018) 1705145.</p>', null, false, 5),
  ('구기갑', null, '명예교수', 'Professor Emeritus', 'koo@sogang.ac.kr', null, null, null, null, null, null, 'MEDIA_BASE/faculty/0550721001726032570.jpg', null, null, '<h3>학력</h3><ul><li>연세대학교 공학사(1981)</li><li>한국과학기술원 공학석사(1984)</li><li>Rensselaer Polytechnic Institute 공학박사(1991)</li></ul>', null, true, 2),
  ('신희종', 'Heejong Shin', '조교수', 'Assistant Professor', 'hshin@sogang.ac.kr', '02-705-8921', '전기화학 에너지 변환 연구실(Electrochemical Energy Conversion Laboratory)', 'Electrochemical Energy Conversion Laboratory', 'http://hshin-lab.com/', 'R', '603A', 'MEDIA_BASE/faculty/0717924001739755226.jpg', 'Electrochemistry, Electrocatalysis, Energy Conversion & Storage, in situ Analysis', '<p class="text-lg font-semibold">Electrochemistry, Electrocatalysis, Energy Conversion &amp; Storage, in situ Analysis</p><p>Fundamental Electrochemistry for Energy Applications<br>The efficiency of energy conversion (electrocatalysis for fuel cell, water electrolyzer, CO2 capture/conversion, and H2O2 generation) and energy storage (organic and aqueous electrolyte batteries) is predominantly determined by electrochemical properties that regulate interfacial charge transfer and various molecular interactions. These fundamental reactions play a pivotal role in practical applications, including renewable energy conversion and storage, chemical or fuels production, and so on. Considering that the overall electrochemical performance relies on a deep understanding and strategic design of electrocatalytic materials and reaction environments, our research group focuses on both elucidating fundamental reaction mechanisms and applying our findings to real-world technologies.</p><p>Electrochemical Energy Engineering and CO2 Utilization<br>With the increasing availability of renewable electricity, many industries are transitioning to electrification to reduce their carbon footprint. However, chemical manufacturing faces challenges, as conventional thermochemical routes are often difficult to electrify. Our research group is developing electrocatalytic technologies to produce chemical fuels and feedstock using renewable electricity and water. We conduct fundamental studies on catalyst materials and work toward their integration into full electrolyzer systems. Our efforts extend to engineering gas diffusion layers and membrane electrode assemblies with industrially relevant performance metrics. We aim to apply this approach to various electrochemical routes with high potential, including: 1) The conversion of CO2 into chemical feedstock and renewable fuels, along with carbon capture from air, 2) The upgrading of hydrocarbons and low-cost feedstock into high-value chemicals, and 3) The development of electrocatalysts and interfaces for efficient energy applications.</p>', '<h3>학력</h3><ul><li>서울대학교 공학사 (2014)</li><li>서울대학교 공학박사 (2020)</li></ul><h3>경력</h3><ul><li>2020-2022, 박사후 연구원(서울대학교)</li><li>2023-2025, 박사후 연구원(Northwestern University)</li></ul><h3>주요 논문</h3><p>“Durable and Active Nitrogen-Coordinated Iron Single-Atom Catalyst for Proton Exchange Membrane Fuel Cells Through Carbon Encapsulation” Advanced Energy Materials 14 (2024) 2400565.rn“Electrochemically generated electrophilic peroxo species accelerates alkaline oxygen evolution reaction”, Joule 7 (2023), 1902-1919.rn“Supramolecular tuning of supported metal phthalocyanine catalysts for hydrogen peroxide electrosynthesis”, Nature Catalysis 6 (2023) 234-243.rn“Carbon Shell on Active Nanocatalyst for Stable Electrocatalysis”, Accounts of Chemical Research 55 (2022) 1278-1289.rn“Atomic-level Tuning of Co-N-C Catalyst for High-Performance Electrochemical H2O2 Production”, Nature Materials 19 (2020) 436-44.</p>', null, false, 3);

